from __future__ import annotations
import os, sys, json, base64, io
import numpy as np
#!/usr/bin/env python3
"""Feature extraction for the v58 learned option-scorer policy.

STATE: fixed vector describing the board from the deciding player's view.
OPTION: fixed vector per legal option (card stats, target stats, attack math).
Self-contained apart from a card_index dict ({cards: {id: rec}, attacks: {id: rec}}).
"""

DS = 96
DO = 64
MAX_OPT = 32

_OTYPES = 16
_AREAS = 13


def _f(x, default=0.0):
    try:
        return float(x)
    except Exception:
        return default


class Featurizer:
    def __init__(self, card_index: dict):
        self.cards = card_index.get("cards") or {}
        self.attacks = card_index.get("attacks") or {}

    def card(self, cid):
        if cid is None:
            return {}
        return self.cards.get(str(int(cid))) or {}

    def attack(self, aid):
        if aid is None:
            return {}
        return self.attacks.get(str(int(aid))) or {}

    def card_feats(self, cid):
        """14-dim card summary."""
        c = self.card(cid)
        if not c:
            return [0.0] * 14
        atks = c.get("atk") or []
        best_dmg, min_cost = 0.0, 4.0
        for aid in atks:
            a = self.attack(aid)
            best_dmg = max(best_dmg, _f(a.get("d")))
            e = a.get("e") or []
            min_cost = min(min_cost, float(len(e)) if e else 4.0)
        ex = 1.0 if c.get("ex") else 0.0
        mex = 1.0 if c.get("mex") else 0.0
        prize = 3.0 if mex else (2.0 if ex else 1.0)
        return [
            1.0 if c.get("ct") == 0 else 0.0,          # pokemon
            1.0 if c.get("b") else 0.0,                # basic
            _f(c.get("et")) / 3.0,                     # stage
            _f(c.get("hp")) / 350.0,
            ex, mex,
            1.0 if c.get("ace") else 0.0,
            _f(c.get("rc")) / 4.0,                     # retreat cost
            best_dmg / 300.0,
            min_cost / 4.0,
            prize / 3.0,
            _f(c.get("en")) / 12.0,                    # energy type
            1.0 if (c.get("ct") in (1, 2)) else 0.0,   # item/tool
            1.0 if c.get("ct") == 3 else 0.0,          # supporter
        ]

    def _poke_block(self, poke):
        """10-dim summary of one in-play pokemon dict (or zeros)."""
        if not isinstance(poke, dict):
            return [0.0] * 10
        cid = poke.get("id")
        c = self.card(cid)
        hp = _f(c.get("hp"))
        cur_hp = hp - _f(poke.get("damage", poke.get("damageCounter", 0))) * 1.0
        # engine uses damage counters in units of 10 sometimes; guard both
        dmg = _f(poke.get("damage", 0))
        if dmg > hp and hp > 0:
            dmg = dmg / 10.0
        cur_hp = max(hp - dmg, 0.0)
        energies = poke.get("energies") or poke.get("energy") or []
        n_en = len(energies) if isinstance(energies, list) else _f(energies)
        atks = c.get("atk") or []
        best = 0.0
        for aid in atks:
            best = max(best, _f(self.attack(aid).get("d")))
        ex = 1.0 if c.get("ex") else 0.0
        mex = 1.0 if c.get("mex") else 0.0
        return [
            (cur_hp / hp) if hp > 0 else 0.0,
            hp / 350.0,
            min(n_en, 8) / 8.0,
            _f(c.get("et")) / 3.0,
            ex, mex,
            (3.0 if mex else (2.0 if ex else 1.0)) / 3.0,
            best / 300.0,
            1.0 if poke.get("id") is not None else 0.0,
            min(_f(poke.get("tool", 0)) if isinstance(poke.get("tool"), (int, float)) else (1.0 if poke.get("tool") else 0.0), 1.0),
        ]

    def _board_block(self, player):
        """active block (10) + bench aggregate (8)."""
        if not isinstance(player, dict):
            return [0.0] * 18
        active = player.get("active") or []
        act = self._poke_block(active[0] if active else None)
        bench = [p for p in (player.get("bench") or []) if isinstance(p, dict)]
        agg = [0.0] * 8
        if bench:
            blocks = [self._poke_block(p) for p in bench[:5]]
            agg[0] = len(blocks) / 5.0
            agg[1] = sum(b[0] for b in blocks) / 5.0
            agg[2] = max(b[7] for b in blocks)
            agg[3] = sum(b[2] for b in blocks) / 2.0
            agg[4] = sum(b[4] + b[5] for b in blocks) / 5.0
            agg[5] = sum(b[6] for b in blocks) / 2.0
            agg[6] = max(b[1] for b in blocks)
            agg[7] = 1.0
        return act + agg

    def state_feats(self, obs, me):
        cur = obs.get("current") or {}
        players = cur.get("players") or [{}, {}]
        if len(players) < 2:
            return [0.0] * DS
        opp = 1 - me
        mp, op = players[me], players[opp]
        out = []
        out.append(min(_f(cur.get("turn")), 40) / 40.0)
        out.append(1.0 if cur.get("firstPlayer") == me else 0.0)
        out.append(1.0 if cur.get("supporterPlayed") else 0.0)
        out.append(1.0 if cur.get("energyAttached") else 0.0)
        out.append(1.0 if cur.get("retreated") else 0.0)
        out.append(1.0 if cur.get("stadium") else 0.0)
        out.append((6 - len(mp.get("prize") or [])) / 6.0)
        out.append((6 - len(op.get("prize") or [])) / 6.0)
        out.append(_f(mp.get("deckCount")) / 60.0)
        out.append(_f(op.get("deckCount")) / 60.0)
        out.append(min(_f(mp.get("handCount", len(mp.get("hand") or []))), 15) / 15.0)
        out.append(min(_f(op.get("handCount", len(op.get("hand") or []))), 15) / 15.0)
        disc = mp.get("discard") or []
        water_disc = sum(1 for d in disc if isinstance(d, dict) and self.card(d.get("id")).get("en") == 3)
        out.append(min(len(disc), 40) / 40.0)
        out.append(min(water_disc, 20) / 20.0)
        out.append(min(_f(cur.get("turnActionCount")), 20) / 20.0)
        out.append(1.0 if me == cur.get("yourIndex") else 0.0)
        out += self._board_block(mp)   # 18
        out += self._board_block(op)   # 18
        # hand composition (mine only)
        hand = mp.get("hand") or []
        basics = sum(1 for h in hand if isinstance(h, dict) and self.card(h.get("id")).get("b"))
        energies = sum(1 for h in hand if isinstance(h, dict) and self.card(h.get("id")).get("ct") in (5, 6))
        out.append(min(len(hand), 15) / 15.0)
        out.append(min(basics, 6) / 6.0)
        out.append(min(energies, 8) / 8.0)
        # pad to DS
        out = out[:DS]
        out += [0.0] * (DS - len(out))
        return out

    def _resolve_card(self, opt, obs, me):
        if opt.get("cardId") is not None:
            return opt.get("cardId")
        area, idx = opt.get("area"), opt.get("index")
        if idx is None:
            return None
        cur = obs.get("current") or {}
        players = cur.get("players") or []
        owner = opt.get("playerIndex", me)
        try:
            if area == 2 and owner == me:  # HAND
                hand = players[me].get("hand") or []
                return (hand[idx] or {}).get("id") if 0 <= idx < len(hand) else None
            if area == 1 and owner == me:  # DECK via select deck reveal
                deck = (obs.get("select") or {}).get("deck") or []
                if 0 <= idx < len(deck):
                    e = deck[idx]
                    return e.get("id") if isinstance(e, dict) else e
                return None
            # board areas
            zone = "active" if area == 4 else ("bench" if area == 5 else None)
            if zone and 0 <= owner < len(players):
                z = players[owner].get(zone) or []
                return (z[idx] or {}).get("id") if 0 <= idx < len(z) else None
        except Exception:
            return None
        return None

    def _target_poke(self, opt, obs, me):
        area = opt.get("inPlayArea")
        idx = opt.get("inPlayIndex")
        if area not in (4, 5) or idx is None:
            return None, None
        cur = obs.get("current") or {}
        players = cur.get("players") or []
        zone = "active" if area == 4 else "bench"
        cands = []
        for owner in (me, 1 - me):
            if 0 <= owner < len(players):
                z = players[owner].get(zone) or []
                if 0 <= idx < len(z) and isinstance(z[idx], dict):
                    cands.append((owner, z[idx]))
        # ATTACH/EVOLVE target own, others default to first found (mine preferred ordering above is me first)
        if opt.get("type") in (8, 9):
            return (me, cands[0][1]) if cands else (None, None)
        return cands[0] if cands else (None, None)

    def option_feats(self, opt, obs, me, state_cache=None):
        cur = obs.get("current") or {}
        players = cur.get("players") or [{}, {}]
        opp = 1 - me
        out = [0.0] * DO
        otype = int(opt.get("type") or 0)
        if 0 <= otype < _OTYPES:
            out[otype] = 1.0
        area = int(opt.get("area") or 0)
        if 0 <= area < _AREAS:
            out[16 + area] = 1.0
        ipa = int(opt.get("inPlayArea") or 0)
        if 0 <= ipa < _AREAS:
            out[29 + ipa] = 1.0
        cid = self._resolve_card(opt, obs, me)
        cf = self.card_feats(cid)
        out[42:56] = cf
        # attack-specific
        if otype == 13:  # ATTACK
            a = self.attack(opt.get("attackId"))
            dmg = _f(a.get("d"))
            cost = len(a.get("e") or [])
            opp_active = (players[opp].get("active") or [None])[0] if len(players) > opp else None
            blk = self._poke_block(opp_active)
            out[56] = dmg / 300.0
            out[57] = cost / 4.0
            out[58] = 1.0 if (blk[0] * blk[1] * 350.0) <= dmg and dmg > 0 else 0.0  # lethal on active
            out[59] = (dmg / 300.0) * blk[6]  # damage x prize value
        # target pokemon block summary (4)
        towner, tpoke = self._target_poke(opt, obs, me)
        if tpoke is not None:
            tb = self._poke_block(tpoke)
            out[60] = tb[0]
            out[61] = tb[2]
            out[62] = tb[6]
            out[63] = 1.0 if towner == me else 0.0
        return out
"""Features for the RL policy: board tokens (transformer input), global state
(96d, tools/policy_feats), per-option features (64d) + belief features.

Belief: BeliefTracker utrzymuje per gre zbior kart przeciwnika juz widzianych
(lawka/aktywny/odrzucone + logi), zeby model mogl szacowac niewidoczna reke.
"""
import sys
sys.path.insert(0, 'tools')
from policy_feats import Featurizer, DS, DO, MAX_OPT  # noqa: E402

TOK_DIM = 14
MAX_TOK = 13  # 6 swoich + 6 opp + token globalny


class BeliefTracker:
    """Widoczne karty przeciwnika w trakcie jednej gry."""
    def __init__(self):
        self.reset()

    def reset(self):
        self.opp_seen = {}       # card_id -> liczba widzianych kopii (stale)
        self.opp_discard_seen = {}

    def observe(self, obs, me):
        try:
            cur = obs.get("current") or {}
            players = cur.get("players") or []
            if len(players) < 2:
                return
            opp = players[1 - me]
            for zone in ("active", "bench"):
                for c in opp.get(zone) or []:
                    if isinstance(c, dict) and c.get("id") is not None:
                        self.opp_seen[int(c["id"])] = self.opp_seen.get(int(c["id"]), 0) + 0  # tylko obecnosc
            for c in opp.get("discard") or []:
                if isinstance(c, dict) and c.get("id") is not None:
                    self.opp_discard_seen[int(c["id"])] = self.opp_discard_seen.get(int(c["id"]), 0) + 1
        except Exception:
            pass

    def feats(self, obs, me):
        """8d: ile juz wiemy o talii/rece przeciwnika."""
        try:
            cur = obs.get("current") or {}
            players = cur.get("players") or []
            opp = players[1 - me]
            board_n = 0
            for zone in ("active", "bench"):
                board_n += sum(1 for c in opp.get(zone) or [] if isinstance(c, dict))
            disc_n = len(opp.get("discard") or [])
            return [
                min(len(self.opp_seen), 20) / 20.0,
                min(sum(self.opp_discard_seen.values()), 30) / 30.0,
                min(board_n, 6) / 6.0,
                min(disc_n, 40) / 40.0,
                min(float(opp.get("handCount") or 0), 15) / 15.0,
                min(float(opp.get("deckCount") or 0), 60) / 60.0,
                min(len(opp.get("prize") or []), 6) / 6.0,
                1.0 if board_n else 0.0,
            ]
        except Exception:
            return [0.0] * 8


class RLFeaturizer:
    def __init__(self, card_index):
        self.fz = Featurizer(card_index)
        self.belief = BeliefTracker()

    def tokens(self, obs, me):
        """[MAX_TOK x TOK_DIM]: moje pokemony, opp pokemony, token globalny."""
        fz = self.fz
        cur = obs.get("current") or {}
        players = cur.get("players") or [{}, {}]
        toks = []
        for side, pl in ((0, players[me] if len(players) > me else {}),
                         (1, players[1 - me] if len(players) > 1 - me else {})):
            act = pl.get("active") or []
            slots = [act[0] if act else None] + list(pl.get("bench") or [])[:5]
            slots += [None] * (6 - len(slots))
            for pos, pk in enumerate(slots[:6]):
                blk = fz._poke_block(pk)
                toks.append(blk + [float(side), pos / 5.0,
                                   1.0 if pos == 0 else 0.0,
                                   1.0 if pk else 0.0])
        g = fz.state_feats(obs, me)
        toks.append([x for x in g[:10]] + [0.0, 0.0, 0.0, 1.0])  # global token marker
        return toks

    def encode(self, obs, me):
        """Zwraca (tokens, state(96+8 belief), options[MAX_OPT x DO], mask, nopts)."""
        self.belief.observe(obs, me)
        st = self.fz.state_feats(obs, me) + self.belief.feats(obs, me)
        sel = obs.get("select") or {}
        raw = sel.get("option") or []
        n = min(len(raw), MAX_OPT)
        opts = [[0.0] * DO for _ in range(MAX_OPT)]
        mask = [0.0] * MAX_OPT
        for i in range(n):
            try:
                opts[i] = self.fz.option_feats(raw[i], obs, me)
                mask[i] = 1.0
            except Exception:
                pass
        return self.tokens(obs, me), st, opts, mask, n
"""Forward PolicyNet w czystym numpy (parytet z Flax) - do agenta Kaggle."""
import numpy as np

P = "/params/"


def _dense(x, W, name):
    return x @ W[P + name + "/kernel"] + W[P + name + "/bias"]


def _ln(x, W, name, eps=1e-6):
    mu = x.mean(-1, keepdims=True)
    var = x.var(-1, keepdims=True)
    return (x - mu) / np.sqrt(var + eps) * W[P + name + "/scale"] + W[P + name + "/bias"]


def _gelu(x):
    return 0.5 * x * (1.0 + np.tanh(np.sqrt(2.0 / np.pi) * (x + 0.044715 * x ** 3)))


def _attn(x, W, name):
    q = np.einsum('btd,dhk->bthk', x, W[P + name + "/query/kernel"]) + W[P + name + "/query/bias"]
    k = np.einsum('btd,dhk->bthk', x, W[P + name + "/key/kernel"]) + W[P + name + "/key/bias"]
    v = np.einsum('btd,dhk->bthk', x, W[P + name + "/value/kernel"]) + W[P + name + "/value/bias"]
    att = np.einsum('bthk,bshk->bhts', q, k) / np.sqrt(q.shape[-1])
    att = np.exp(att - att.max(-1, keepdims=True))
    att = att / att.sum(-1, keepdims=True)
    o = np.einsum('bhts,bshk->bthk', att, v)
    return np.einsum('bthk,hkd->btd', o, W[P + name + "/out/kernel"]) + W[P + name + "/out/bias"]


def forward(W, tokens, state, opts, omask):
    x = _dense(tokens, W, "Dense_0")
    for i in range(3):
        x = _ln(x + _attn(x, W, f"MultiHeadDotProductAttention_{i}"), W, f"LayerNorm_{2*i}")
        y = _dense(_gelu(_dense(x, W, f"Dense_{1+2*i}")), W, f"Dense_{2+2*i}")
        x = _ln(x + y, W, f"LayerNorm_{2*i+1}")
    board_ctx = x.mean(1)
    g = _gelu(_dense(state, W, "Dense_7"))
    ctx = _dense(_ln(board_ctx + g, W, "LayerNorm_6"), W, "Dense_8")
    o = _dense(_gelu(_dense(opts, W, "Dense_9")), W, "Dense_10")
    logits = np.einsum('bod,bd->bo', o, ctx) / np.sqrt(ctx.shape[-1])
    logits = logits + (1.0 - omask) * (-1e9)
    value = _dense(_gelu(_dense(ctx, W, "Dense_12")), W, "Dense_11")[:, 0]
    return logits, value
_WEIGHTS_B64 = """"""
_CHAMP_B64 = """"""
_W=None; _RFZ=None; _CI=None; _CHAMP_AGENT=None
def _cand():
    d=[]
    try:
        d.append(os.path.dirname(os.path.abspath(__file__)))
    except:
        pass
    d.append(os.getcwd()); d.append("/kaggle_simulations/agent"); return d
def _load_ci():
    global _CI
    if _CI is not None:
        return _CI
    for dd in _cand():
        p=os.path.join(dd,"card_index.json")
        if os.path.exists(p):
            try:
                with open(p,encoding="utf-8") as fh:
                    _CI=json.load(fh); return _CI
            except:
                pass
    return {"cards":{}, "attacks":{}}
def _load():
    global _W,_RFZ,_CHAMP_AGENT
    if _W is not None and _CHAMP_AGENT is not None:
        return
    try:
        raw=base64.b64decode(_WEIGHTS_B64)
        _W=dict(np.load(io.BytesIO(raw)))
        _RFZ=RLFeaturizer(_load_ci())
    except Exception:
        _W=None; _RFZ=None
    try:
        code=base64.b64decode(_CHAMP_B64).decode()
        ns={}
        exec(code, ns)
        _CHAMP_AGENT=ns.get("agent")
        if "DECK" in ns:
            globals()["_CHAMP_DECK"]=ns["DECK"]
    except Exception:
        _CHAMP_AGENT=None
def _fallback(obs):
    try:
        if _CHAMP_AGENT is not None:
            return _CHAMP_AGENT(obs)
    except Exception:
        pass
    try:
        sel=obs.get("select") or {}
        opts=sel.get("option") or []
        if not opts:
            return []
        maxc=int(sel.get("maxCount") or 1)
        if maxc<=0:
            return []
        return list(range(min(maxc, len(opts))))
    except Exception:
        return [0]

def _active_simple(obs, pidx):
    try:
        pl=obs["current"]["players"][pidx]
        act=pl.get("active") or []
        return act[0] if act else None
    except Exception:
        return None

def _est_dmg_simple(aid, ci):
    try:
        if aid is None:
            return 0
        atks=ci.get("attacks") or {}
        a=atks.get(str(int(aid))) or {}
        return int(a.get("d") or 0)
    except Exception:
        return 0

def _is_lethal(opt, obs, me, opp, ci):
    try:
        # attack type 13
        if int(opt.get("type") or -1) != 13:
            return False
        aid=opt.get("attackId")
        dmg=_est_dmg_simple(aid, ci)
        opp_act=_active_simple(obs, opp)
        if not opp_act:
            return False
        # get HP
        cid=opp_act.get("id")
        cards=ci.get("cards") or {}
        c=cards.get(str(int(cid))) if cid is not None else {}
        hp=int(c.get("hp") or 0) if c else 0
        cur_dmg=int(opp_act.get("damage") or 0)
        remaining=hp - cur_dmg
        return dmg >= remaining and remaining>0
    except Exception:
        return False


def agent(obs):
    _load()
    try:
        if not isinstance(obs, dict):
            return _fallback(obs)
        if obs.get("select") is None:
            try:
                if _CHAMP_AGENT is not None:
                    d=_CHAMP_AGENT(obs)
                    if isinstance(d, list) and len(d)==60:
                        return d
            except:
                pass
            for dd in _cand():
                p=os.path.join(dd,"deck.csv")
                if os.path.exists(p):
                    try:
                        ids=[]
                        with open(p,encoding="utf-8") as fh:
                            for tok in fh.read().replace(","," ").split():
                                try:
                                    ids.append(int(tok))
                                except:
                                    pass
                        if len(ids)==60:
                            return ids
                    except:
                        pass
            try:
                if "_CHAMP_DECK" in globals() and len(globals()["_CHAMP_DECK"])==60:
                    return globals()["_CHAMP_DECK"]
            except:
                pass
            return []
        sel=obs.get("select") or {}
        tt=sel.get("type")
        if _W is not None and tt is not None and int(tt)==0 and int(sel.get("maxCount") or 1)==1:
            cur=obs.get("current") or {}
            me=int(cur.get("yourIndex",0))
            enc=_RFZ.encode(obs, me)
            tok=np.array([enc[0]], np.float32); st=np.array([enc[1]], np.float32)
            opts=np.array([enc[2]], np.float32); mask=np.array([enc[3]], np.float32)
            logits,_=forward(_W, tok, st, opts, mask)
            n=max(enc[4],1)
            lg=logits[0][:n]
            # lethal check +2000 boost (7th place technique)
            try:
                sel=obs.get("select") or {}
                raw_opts=sel.get("option") or []
                for i in range(min(n, len(raw_opts))):
                    if _is_lethal(raw_opts[i], obs, me, 1-me, _load_ci()):
                        lg[i] += 2000
            except Exception:
                pass
            # gated search margin>=250 endgame
            try:
                cur=obs.get("current") or {}
                players=cur.get("players") or []
                if len(players)>=2:
                    me_p=players[me]; opp_p=players[1-me]
                    my_rem=len(me_p.get("prize") or []); opp_rem=len(opp_p.get("prize") or [])
                    if my_rem<=3 or opp_rem<=3:
                        # penalize non-lethal attacks that don't KO when we are behind
                        for i in range(min(n, len(raw_opts))):
                            if int(raw_opts[i].get("type") or -1)==13:
                                aid=raw_opts[i].get("attackId")
                                dmg=_est_dmg_simple(aid, _load_ci())
                                opp_act=_active_simple(obs, 1-me)
                                if opp_act:
                                    cid=opp_act.get("id")
                                    cards=_load_ci().get("cards") or {}
                                    c=cards.get(str(int(cid))) if cid is not None else {}
                                    hp=int(c.get("hp") or 0) if c else 0
                                    cur_dmg=int(opp_act.get("damage") or 0)
                                    rem=hp-cur_dmg
                                    margin=dmg-rem
                                    if margin>=0:
                                        lg[i]+=200
                                    elif margin>=-50 and my_rem<=2 and opp_rem==1:
                                        # close but not enough, and we would give 2 prizes
                                        lg[i]-=200
            except Exception:
                pass
            return [int(np.argmax(lg))]
        else:
            return _fallback(obs)
    except Exception:
        return _fallback(obs)
